BlockingQueue<Job> queue = new ArrayBlockingQueue<>(100);
ExecutorService pool = Executors.newFixedThreadPool(n);
for (int i = 0; i < n; i++) {
    pool.submit(() -> {
        while (!Thread.currentThread().isInterrupted()) {
            Job job = queue.take();          // exactly one worker gets each job
            try { process(job); }            // ack AFTER success
            catch (Exception e) { requeueOrDeadLetter(job, e); }
        }
    });
}

